"use client"

import * as React from "react"
import {
  GlimmProvider,
  useGlimm,
  type GlimmDefaults,
  type PaletteName,
} from "glimm/react"

const PRESETS = [
  {
    name: "spectrum",
    gradient:
      "linear-gradient(90deg in oklch, oklch(0.831 0.139 72) 0%, oklch(0.699 0.226 351.9) 14%, oklch(0.674 0.289 320.6) 29%, oklch(0.649 0.189 276) 43%, oklch(0.878 0.138 202.9) 57%, oklch(0.896 0.184 152.9) 71%, oklch(0.938 0.2 122.8) 86%, oklch(0.831 0.139 72) 100%)",
  },
  {
    name: "prism",
    gradient:
      "linear-gradient(90deg in oklch, oklch(0.736 0.139 224.3) 0%, oklch(0.696 0.156 238.9) 14%, oklch(0.64 0.186 253.1) 29%, oklch(0.591 0.215 267.1) 43%, oklch(0.571 0.236 284.3) 57%, oklch(0.583 0.252 301.2) 71%, oklch(0.605 0.258 312.8) 86%, oklch(0.619 0.248 318.1) 100%)",
  },
  {
    name: "berry",
    gradient:
      "linear-gradient(90deg in oklch, oklch(0.644 0.236 13.7) 0%, oklch(0.646 0.242 11) 14%, oklch(0.644 0.245 4.6) 29%, oklch(0.639 0.248 355.3) 43%, oklch(0.633 0.254 345) 57%, oklch(0.629 0.259 335.9) 71%, oklch(0.625 0.261 329.5) 86%, oklch(0.622 0.256 326.7) 100%)",
  },
  {
    name: "lagoon",
    gradient:
      "linear-gradient(90deg in oklch, oklch(0.629 0.172 249.1) 0%, oklch(0.669 0.182 248.4) 14%, oklch(0.705 0.169 242.4) 29%, oklch(0.735 0.146 229.8) 43%, oklch(0.753 0.129 206.5) 57%, oklch(0.757 0.137 180.1) 71%, oklch(0.746 0.16 162.8) 86%, oklch(0.721 0.178 154.3) 100%)",
  },
  {
    name: "citrus",
    gradient:
      "linear-gradient(90deg in oklch, oklch(0.724 0.184 143.4) 0%, oklch(0.769 0.197 132.8) 14%, oklch(0.809 0.187 119.2) 29%, oklch(0.838 0.175 101) 43%, oklch(0.843 0.173 84.8) 57%, oklch(0.813 0.17 76.5) 71%, oklch(0.782 0.17 66.7) 86%, oklch(0.723 0.148 64.1) 100%)",
  },
  {
    name: "azure",
    gradient:
      "linear-gradient(90deg in oklch, oklch(0.731 0.138 224.8) 0%, oklch(0.722 0.146 231.4) 14%, oklch(0.696 0.162 241) 29%, oklch(0.658 0.185 250.2) 43%, oklch(0.619 0.208 257.6) 57%, oklch(0.589 0.222 264.7) 71%, oklch(0.576 0.225 272.4) 86%, oklch(0.577 0.217 279.3) 100%)",
  },
  {
    name: "ember",
    gradient:
      "linear-gradient(90deg in oklch, oklch(0.835 0.172 82.8) 0%, oklch(0.836 0.172 82.9) 14%, oklch(0.813 0.17 76.3) 29%, oklch(0.773 0.171 64) 43%, oklch(0.729 0.182 49.2) 57%, oklch(0.692 0.201 36) 71%, oklch(0.669 0.218 27) 86%, oklch(0.659 0.227 22.5) 100%)",
  },
] satisfies ReadonlyArray<{ name: PaletteName; gradient: string }>

const highlight =
  "radial-gradient(120% 95% at 50% 12%, rgba(255,255,255,0.32) 0%, rgba(255,255,255,0.08) 40%, rgba(255,255,255,0) 58%)"

type GlimmPresetsProps = Omit<GlimmDefaults, "palette"> & {
  className?: string
}

function EyeIcon() {
  return (
    <svg
      aria-hidden="true"
      fill="none"
      height="18"
      viewBox="0 0 24 24"
      width="18"
    >
      <path
        clipRule="evenodd"
        d="M12.0015 4C15.8807 4.00003 19.6594 6.31907 22.1829 10.7475C22.6254 11.524 22.6254 12.476 22.1829 13.2526C19.6594 17.681 15.8806 20 12.0015 19.9999C8.12239 19.9999 4.34363 17.6809 1.82016 13.2524C1.37766 12.4759 1.37766 11.5239 1.82016 10.7474C4.34363 6.31896 8.1224 3.99997 12.0015 4ZM8.3765 12C8.3765 9.99797 9.99947 8.375 12.0015 8.375C14.0036 8.375 15.6265 9.99797 15.6265 12C15.6265 14.002 14.0036 15.625 12.0015 15.625C9.99947 15.625 8.3765 14.002 8.3765 12Z"
        fill="currentColor"
        fillRule="evenodd"
      />
    </svg>
  )
}

function PresetList() {
  const { sweep } = useGlimm()

  const preview = React.useCallback(
    (palette: PaletteName) => sweep(() => undefined, { palette }),
    [sweep],
  )

  return (
    <div>
      {PRESETS.map((preset, index) => (
        <div
          key={preset.name}
          onClick={() => preview(preset.name)}
          onKeyDown={(event) => {
            if (event.key === "Enter" || event.key === " ") {
              event.preventDefault()
              preview(preset.name)
            }
          }}
          role="button"
          tabIndex={0}
          style={{
            alignItems: "center",
            borderTop: index === 0 ? "none" : "1px solid #ececec",
            cursor: "pointer",
            display: "grid",
            gap: "13px",
            gridTemplateColumns: "90px minmax(0, 1fr) 90px",
            opacity: 1,
            padding: "8px 0",
            textAlign: "left",
            transition: "opacity 160ms ease",
            width: "100%",
          }}
        >
          <span
            style={{
              color: "#242529",
              fontFamily: "Inter, ui-sans-serif, system-ui, sans-serif",
              fontSize: "13px",
              fontVariationSettings: '"wght" 450',
              fontWeight: 450,
              letterSpacing: "-0.18px",
              lineHeight: "18px",
            }}
          >
            {preset.name}
          </span>

          <span
            aria-hidden="true"
            style={{
              background: `${highlight}, ${preset.gradient}`,
              borderRadius: "999px",
              boxShadow:
                "inset 0 0.5px 1px rgba(255,255,255,0.45), inset 0 0 0 0.5px rgba(0,0,0,0.06), 0 0.5px 1.5px rgba(0,0,0,0.12)",
              height: "14px",
            }}
          />

          <span style={{ display: "inline-flex", justifySelf: "end" }}>
            <button
              aria-label={`Preview ${preset.name}`}
              onClick={(event) => {
                event.stopPropagation()
                preview(preset.name)
              }}
              type="button"
              style={{
                alignItems: "center",
                background: "transparent",
                border: "none",
                borderRadius: "999px",
                color: "#bfbfbf",
                cursor: "pointer",
                display: "inline-flex",
                height: "24px",
                justifyContent: "center",
                padding: "0 6px",
                transition:
                  "color 160ms cubic-bezier(0.23, 1, 0.32, 1), transform 160ms cubic-bezier(0.23, 1, 0.32, 1)",
              }}
            >
              <EyeIcon />
            </button>
          </span>
        </div>
      ))}
    </div>
  )
}

function GlimmPresets({ className, ...defaults }: GlimmPresetsProps) {
  return (
    <GlimmProvider {...defaults}>
      <main
        className={className}
        style={{
          alignItems: "center",
          background: "#ffffff",
          color: "#242529",
          display: "flex",
          justifyContent: "center",
          minHeight: "100vh",
          padding: "48px 32px",
          width: "100%",
        }}
      >
        <section style={{ maxWidth: "634px", width: "100%" }}>
          <PresetList />
        </section>
      </main>
    </GlimmProvider>
  )
}

export { GlimmPresets, PRESETS }
export default GlimmPresets

